SELECT mi1.info, pi.info, COUNT(*)
FROM title as t, kind_type as kt, movie_info as mi1, info_type as it1, cast_info as ci, role_type as rt, name as n, info_type as it2, person_info as pi, non_leaf_1101
WHERE (rt.role IN ('actor','composer','director','editor','miscellaneous crew','producer')) AND (pi.info ILIKE '%194%') AND (mi1.info ILIKE '%roma%') AND (it1.id IN ('16')) AND (kt.kind IN ('movie','tv mini series','tv movie','video game','video movie')) AND it1.id = non_leaf_1101.mi1_info_type_id AND it2.id = non_leaf_1101.pi_info_type_id AND (it2.id IN ('23'));